#!/usr/bin/env bash
# 式神（お守り）のアイコン。8体ずつ 4列×2行 で並べ、split で切り分ける
cd ~/Projects/konkon-hanafuda
S="A sprite sheet of 8 separate cute chibi yokai mascot icons for a game, arranged in a neat grid of 4 columns and 2 rows with wide empty gaps between them, each icon a single small round chunky character or object, thick clean dark outlines, flat cel shading, warm saturated colors, cute kemono anime style, all-ages. Plain flat pure green (#00FF00) background, no text, no frames. In reading order (left to right, top row first):"
tools/gen_image.sh art/raw/charms_1.png "$S (1) a beckoning maneki-neko lucky cat, (2) a round tanuki drumming on its big belly, (3) a kappa holding up the water dish from its head, (4) ittan-momen, a long flying white cloth spirit with eyes, (5) a red tengu mask with a long nose, (6) a blue onibi will-o'-wisp flame with a cute face, (7) zashiki-warashi, a tiny child spirit in a red kimono with a bob haircut holding a coin, (8) rokurokubi, a smiling lady head on a very long looping neck." &
tools/gen_image.sh art/raw/charms_2.png "$S (1) a bake-chochin paper lantern yokai with one eye and a long tongue, (2) yuki-onna, a pale snow spirit in a white kimono blowing snowflakes, (3) a nopperabo faceless round blank-faced spirit with a sweat drop, (4) karakasa-obake, a one-eyed paper umbrella hopping on one leg, (5) kasha, a flaming cat pulling a burning wheel, (6) a single huge fluffy golden fox tail with a bell, (7) a two-tailed nekomata cat bell charm, (8) gashadokuro, a cute giant skeleton skull." &
tools/gen_image.sh art/raw/charms_3.png "$S (1) binbogami, a scrawny poverty god holding a fan and an empty wallet, (2) shuten-doji, a red oni with a huge red sake cup, (3) umibozu, a big round black sea monk head rising from waves, (4) hitotsume-kozo, a little bald monk boy with one big eye, (5) inugami, a white dog spirit with a coin in its mouth, (6) a baku, a dream-eating tapir creature on a cloud, (7) tsukumogami, an old tea kettle yokai with eyes and gold leaf, (8) a golden koban coin with a happy face." &
wait
